#include "hip_api.h"
using namespace hip_probe;
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("MODULE FUNCTION OUT trace");Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");Handle m{},q{},f{};void*di{},*doo{};a.Check(a.LoadModule(&m,argv[1]),"module");a.Check(a.hipStreamCreate(&q),"stream");a.Check(a.hipModuleGetFunction(&f,m,argv[2]),"function");unsigned n=640;size_t os=32ull*40*32*32*4;std::vector<unsigned char>in(3*n*1024),out(os,0);unsigned rng=12345;for(auto&x:in){rng=rng*1664525+1013904223;x=(rng>>24)&127;x=(x%48)+8;if(rng&128)x|=128;}a.Check(a.hipMalloc(&di,in.size()),"in");a.Check(a.hipMalloc(&doo,os),"out");a.Check(a.hipMemcpy(di,in.data(),in.size(),1),"upload");a.Check(a.hipMemcpy(doo,out.data(),os,1),"clear");void*gate=nullptr;void*args[]={&di,&doo,&n,&gate};a.Check(a.hipModuleLaunchKernel(f,32,1,1,32,1,1,0,q,args,nullptr),"launch");a.Check(a.hipStreamSynchronize(q),"sync");a.Check(a.hipMemcpy(out.data(),doo,os,2),"download");std::ofstream(argv[3],std::ios::binary).write((char*)out.data(),out.size());printf("VIT_PROBE bytes=%zu trace=%s\n",out.size(),argv[4]);a.hipFree(di);a.hipFree(doo);a.hipStreamDestroy(q);a.hipModuleUnload(m);return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
